package com.shopsphere.model;import com.fasterxml.jackson.annotation.JsonIgnoreProperties;import jakarta.persistence.*;@Entity public class OrderItem{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)@JsonIgnoreProperties("items")private ShopOrder order;@ManyToOne(optional=false)private Product product;private Integer quantity;private Double unitPrice;public OrderItem(){}public OrderItem(ShopOrder o,Product p,Integer q,Double price){order=o;product=p;quantity=q;unitPrice=price;}public Long getId(){return id;}public ShopOrder getOrder(){return order;}public void setOrder(ShopOrder x){order=x;}public Product getProduct(){return product;}public void setProduct(Product x){product=x;}public Integer getQuantity(){return quantity;}public void setQuantity(Integer x){quantity=x;}public Double getUnitPrice(){return unitPrice;}public void setUnitPrice(Double x){unitPrice=x;}}